                    $botMessageStats[$row['bot_system']] = [
                        'messages_sent' => $row['messages_sent'],
                        'last_updated' => $row['last_updated']
                    ];
                }
            }
        }
        echo json_encode(['botMessageStats' => $botMessageStats]);
        exit;
    } elseif ($ajax === 'ai_platform_stats') {
        $return_ai_stats_json = true;
        // Give extra time for OpenAI API pagination calls
        set_time_limit(120);
    }
}

// Function to get service status
function getServiceStatus($service_name, $ssh_host, $ssh_username, $ssh_password) {
    $status = 'Unknown';
    $pid = 'N/A';
    if (empty($ssh_host)) {
        return ['status' => $status, 'pid' => $pid];
    }
    try {
        $connection = SSHConnectionManager::getConnection($ssh_host, $ssh_username, $ssh_password);
        if ($connection) {
            $output = SSHConnectionManager::executeCommand($connection, "systemctl status $service_name");
            if ($output) {
                if (preg_match('/Active:\s*active\s*\(running\)/', $output)) {
                    $status = 'Running';
                } elseif (preg_match('/Active:\s*inactive/', $output)) {
                    $status = 'Stopped';
                } elseif (preg_match('/Active:\s*failed/', $output)) {
                    $status = 'Failed';
                }
                if (preg_match('/Main PID:\s*(\d+)/', $output, $matches)) {
                    $pid = $matches[1];
                }
            }
        }
    } catch (Exception $e) {
        $status = 'Error';
        $pid = 'N/A';
    }
    return ['status' => $status, 'pid' => $pid];
}

// Function to get Twitch subscription tier
function getTwitchSubTier($twitch_user_id) {
    global $clientID;
    $accessToken = $_SESSION['access_token'];
    if (empty($twitch_user_id) || empty($accessToken)) {
        return null;
    }
    $broadcaster_id = "140296994";
    $url = "https://api.twitch.tv/helix/subscriptions?broadcaster_id={$broadcaster_id}&user_id={$twitch_user_id}";
    $headers = [ "Client-ID: $clientID", "Authorization: Bearer $accessToken" ];
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($ch);
    if ($response === false) {
return null;
    }
    $data = json_decode($response, true);
// Check if we have subscription data in the response
    if (isset($data['data']) && is_array($data['data']) && count($data['data']) > 0) {
        return $data['data'][0]['tier'];
    }
    return null;
}

// Count non-beta users who subscribe to the broadcaster. Helix accepts up to 100
// user_id values per request, so this is one or two calls instead of one per user.
// Cached in the session for 10 minutes so reloading the admin page stays fast.
function admin_index_premium_subscriber_count($conn) {
    global $clientID;
    $accessToken = $_SESSION['access_token'] ?? '';
    if ($accessToken === '') {
        return 0;
    }
    $cache = $_SESSION['admin_premium_count_cache'] ?? null;
    if (is_array($cache) && isset($cache['at'], $cache['count']) && (time() - (int)$cache['at']) < 600) {
        return (int)$cache['count'];
    }
    $ids = [];
    $result = $conn->query("SELECT twitch_user_id FROM users WHERE twitch_user_id IS NOT NULL AND twitch_user_id != '' AND beta_access = 0");
    if ($result) {
        while ($row = $result->fetch_assoc()) {
            $ids[] = (string)$row['twitch_user_id'];
        }
    }
    $count = 0;
    $ok = true;
    foreach (array_chunk($ids, 100) as $chunk) {
        $query = 'broadcaster_id=140296994&first=100';
        foreach ($chunk as $id) {
            $query .= '&user_id=' . urlencode($id);
        }
        $ch = curl_init('https://api.twitch.tv/helix/subscriptions?' . $query);
        curl_setopt($ch, CURLOPT_HTTPHEADER, ["Client-ID: $clientID", "Authorization: Bearer $accessToken"]);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 3);
        curl_setopt($ch, CURLOPT_TIMEOUT, 5);
        $response = curl_exec($ch);
        $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        if ($response === false || $httpCode !== 200) {
            $ok = false;
            continue;
        }
        $data = json_decode($response, true);
        foreach (($data['data'] ?? []) as $sub) {
            if (in_array((string)($sub['tier'] ?? ''), ['1000', '2000', '3000'], true)) {
                $count++;
            }
        }
    }
    if ($ok) {
        $_SESSION['admin_premium_count_cache'] = ['at' => time(), 'count' => $count];
    }
    return $count;
}

